function calculateMtfAdxAverage(values, period, averageType) {
  const source = Array.isArray(values) ? values : [];
  const length = Math.max(1, Number(period) || 1);
  const type = String(averageType || "WILDERS").toUpperCase();
  const result = new Array(source.length).fill(null);
  if (type === "EXPONENTIAL") {
    const multiplier = 2 / (length + 1);
    let previous = null;
    source.forEach((value, index) => {
      if (!Number.isFinite(value)) return;
      previous = previous == null ? Number(value) : Number(value) * multiplier + previous * (1 - multiplier);
      result[index] = previous;
    });
    return result;
  }
  if (type === "WILDERS") {
    const seed = [];
    let previous = null;
    source.forEach((value, index) => {
      if (!Number.isFinite(value)) return;
      if (previous == null) {
        seed.push(Number(value));
        if (seed.length < length) return;
        previous = seed.slice(-length).reduce((sum, item) => sum + item, 0) / length;
      } else {
        previous = (previous * (length - 1) + Number(value)) / length;
      }
      result[index] = previous;
    });
    return result;
  }
  source.forEach((value, index) => {
    if (!Number.isFinite(value) || index < length - 1) return;
    const window = source.slice(index - length + 1, index + 1);
    if (!window.every(Number.isFinite)) return;
    if (type === "WEIGHTED") {
      const denominator = (length * (length + 1)) / 2;
      result[index] = window.reduce((sum, item, offset) => sum + Number(item) * (offset + 1), 0) / denominator;
    } else {
      result[index] = window.reduce((sum, item) => sum + Number(item), 0) / length;
    }
  });
  return result;
}

