function calculateMtfSqueeze410Average(values, period, averageType) {
  const type = String(averageType || "SIMPLE").toUpperCase();
  if (type !== "HULL") return calculateMtfAdxAverage(values, period, type);
  const length = Math.max(1, Number(period) || 1);
  const halfLength = Math.max(1, Math.round(length / 2));
  const rootLength = Math.max(1, Math.round(Math.sqrt(length)));
  const half = calculateMtfAdxAverage(values, halfLength, "WEIGHTED");
  const full = calculateMtfAdxAverage(values, length, "WEIGHTED");
  const hullSource = values.map((_, index) => (
    Number.isFinite(half[index]) && Number.isFinite(full[index])
      ? 2 * half[index] - full[index]
      : null
  ));
  return calculateMtfAdxAverage(hullSource, rootLength, "WEIGHTED");
}

function aggregateDailyBarsByTradingWeek(bars) {
  const buckets = new Map();
  (Array.isArray(bars) ? bars : []).forEach((bar) => {
    const time = Number(bar?.time || 0);
    if (!Number.isFinite(time) || time <= 0) return;
    const date = new Date(time * 1000);
    const monday = new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate()));
    monday.setUTCDate(monday.getUTCDate() - ((monday.getUTCDay() + 6) % 7));
    const bucketTime = Math.floor(monday.getTime() / 1000);
    const current = buckets.get(bucketTime);
    if (!current) {
      buckets.set(bucketTime, { ...bar, time: bucketTime });
      return;
    }
    current.high = Math.max(Number(current.high || 0), Number(bar?.high || 0));
    current.low = Math.min(Number(current.low || 0), Number(bar?.low || 0));
    current.close = Number(bar?.close || current.close || 0);
    current.volume = Number(current.volume || 0) + Number(bar?.volume || 0);
  });
  return [...buckets.values()].sort((left, right) => Number(left.time) - Number(right.time));
}

function calculateMtfSqueeze410Study(
  displayBars,
  sourceBars,
  dailyBars,
  chartAggregationMinutes,
  options = {},
) {
  const display = Array.isArray(displayBars) ? displayBars : [];
  const intradaySource = Array.isArray(sourceBars) ? sourceBars : [];
  const suppliedDaily = Array.isArray(dailyBars) ? dailyBars : [];
  const chartMinutes = Math.max(1, Number(chartAggregationMinutes) || 5);
  if (!display.length) return [];
  const length = 20;
  const averageType = options.mtfSqueeze410AverageType || "SIMPLE";
  const colors = {
    none: options.mtfSqueeze410NoSqueezeColor || "#000000",
    low: options.mtfSqueeze410LowColor || "#7f6c00",
    mid: options.mtfSqueeze410MidColor || "#ffa500",
    high: options.mtfSqueeze410HighColor || "#ffffff",
  };

  return MTF_SQUEEZE_410_DEFINITIONS.map((definition) => {
    const aggregationMinutes = definition.aggregationKey
      ? Number(options[definition.aggregationKey] || 0)
      : chartMinutes;
    const aggregation = MTF_SQUEEZE_410_AGGREGATION_OPTIONS
      .find(({ value }) => value === aggregationMinutes);
    if (!Number.isFinite(aggregationMinutes) || aggregationMinutes < chartMinutes) {
      return {
        ...definition,
        aggregationMinutes,
        aggregationLabel: aggregation?.label || definition.label,
        data: [],
        latestColor: colors.none,
        latestTone: "none",
      };
    }
    const timeframeBars = aggregationMinutes === chartMinutes
      ? display
      : aggregationMinutes === 1440 && suppliedDaily.length
        ? suppliedDaily
        : aggregationMinutes === 10080 && suppliedDaily.length
          ? aggregateDailyBarsByTradingWeek(suppliedDaily)
          : aggregateChartBars(intradaySource, aggregationMinutes);
    const closes = timeframeBars.map((bar) => Number(bar?.close || 0));
    const trueRanges = calculateTrueRanges(timeframeBars);
    const keltnerAverage = calculateMtfSqueeze410Average(closes, length, averageType);
    const averageTrueRange = calculateMtfSqueeze410Average(trueRanges, length, averageType);
    const bollingerAverage = calculateRollingAverage(closes, length);
    const bollingerDeviation = calculateRollingStdDev(closes, length);
    const classified = timeframeBars.flatMap((bar, index) => {
      if (index < length - 1
        || !Number.isFinite(keltnerAverage[index])
        || !Number.isFinite(averageTrueRange[index])
        || !Number.isFinite(bollingerAverage[index])
        || !Number.isFinite(bollingerDeviation[index])) return [];
      const bollingerUpper = bollingerAverage[index] + 2 * bollingerDeviation[index];
      const keltnerBase = keltnerAverage[index];
      const atr = averageTrueRange[index];
      const highDelta = bollingerUpper - (keltnerBase + atr);
      const midDelta = bollingerUpper - (keltnerBase + 1.5 * atr);
      const lowDelta = bollingerUpper - (keltnerBase + 2 * atr);
      const tone = highDelta <= 0 ? "high" : midDelta <= 0 ? "mid" : lowDelta <= 0 ? "low" : "none";
      return [{
        time: Number(bar.time),
        color: colors[tone],
        tone,
      }];
    });
    let classifiedIndex = -1;
    const data = display.flatMap((bar) => {
      const time = Number(bar?.time || 0);
      while (classifiedIndex + 1 < classified.length
        && Number(classified[classifiedIndex + 1].time) <= time) {
        classifiedIndex += 1;
      }
      if (classifiedIndex < 0) return [];
      return [{
        time,
        value: definition.level + 0.18,
        color: classified[classifiedIndex].color,
      }];
    });
    const latestState = classified[classifiedIndex] || classified.at(-1);
    return {
      ...definition,
      aggregationMinutes,
      aggregationLabel: definition.aggregationKey
        ? (aggregation?.label || definition.label)
        : `${chartMinutes}m`,
      data,
      latestColor: latestState?.color || colors.none,
      latestTone: latestState?.tone || "none",
    };
  });
}

function calculateMtfAdxLines(bars, options = {}) {
  const source = Array.isArray(bars) ? bars : [];
  const length = Math.max(1, Math.min(100, Number(options.mtfAdxLength) || 10));
  if (source.length < 2) {
    return {
      plus: [],
      minus: [],
      adx: [],
      signals: {
        call: [], put: [], strongCall: [], strongPut: [], strongCall2: [], strongPut2: [],
      },
    };
  }
  const trueRanges = [];
  const plusDm = [];
  const minusDm = [];
  source.forEach((bar, index) => {
    const high = Number(bar?.high);
    const low = Number(bar?.low);
    const previous = source[index - 1];
    const previousClose = Number(previous?.close);
    const highDifference = index ? high - Number(previous?.high) : 0;
    const lowDifference = index ? Number(previous?.low) - low : 0;
    trueRanges.push(index
      ? Math.max(high - low, Math.abs(high - previousClose), Math.abs(low - previousClose))
      : high - low);
    plusDm.push(highDifference > lowDifference && highDifference > 0 ? highDifference : 0);
    minusDm.push(lowDifference > highDifference && lowDifference > 0 ? lowDifference : 0);
  });
  const averageType = options.mtfAdxAverageType || "WILDERS";
  const atr = calculateMtfAdxAverage(trueRanges, length, averageType);
  const smoothPlus = calculateMtfAdxAverage(plusDm, length, averageType);
  const smoothMinus = calculateMtfAdxAverage(minusDm, length, averageType);
  const plus = source.map((bar, index) => (
    Number.isFinite(atr[index]) && atr[index] > 0
      ? 100 * Number(smoothPlus[index] || 0) / atr[index]
      : null
  ));
  const minus = source.map((bar, index) => (
    Number.isFinite(atr[index]) && atr[index] > 0
      ? 100 * Number(smoothMinus[index] || 0) / atr[index]
      : null
  ));
  const dx = source.map((bar, index) => {
    if (!Number.isFinite(plus[index]) || !Number.isFinite(minus[index])) return null;
    const total = plus[index] + minus[index];
    return total > 0 ? 100 * Math.abs(plus[index] - minus[index]) / total : 0;
  });
  const adx = calculateMtfAdxAverage(dx, length, averageType);
  const lineData = (values) => source.flatMap((bar, index) => (
    Number.isFinite(values[index])
      ? [{ time: Number(bar.time), value: Number(values[index].toFixed(4)) }]
      : []
  ));
  const signals = {
    call: [],
    put: [],
    strongCall: [],
    strongPut: [],
    strongCall2: [],
    strongPut2: [],
  };
  source.forEach((bar, index) => {
    if (!index || !Number.isFinite(adx[index])) return;
    const plusCrossedMinus = Number(plus[index - 1]) <= Number(minus[index - 1])
      && Number(plus[index]) > Number(minus[index]);
    const minusCrossedPlus = Number(minus[index - 1]) <= Number(plus[index - 1])
      && Number(minus[index]) > Number(plus[index]);
    const plusCrossedStrong = Number(plus[index - 1]) <= 25 && Number(plus[index]) > 25;
    const minusCrossedStrong = Number(minus[index - 1]) <= 25 && Number(minus[index]) > 25;
    const time = Number(bar.time);
    if (plusCrossedMinus) signals.call.push({ time, value: 20 });
    if (minusCrossedPlus) signals.put.push({ time, value: 20 });
    if (plusCrossedStrong) {
      signals.strongCall.push({ time, value: 25 });
      signals.strongCall2.push({ time, value: Number(adx[index].toFixed(4)) });
    }
    if (minusCrossedStrong) {
      signals.strongPut.push({ time, value: 25 });
      signals.strongPut2.push({ time, value: Number(adx[index].toFixed(4)) });
    }
  });
  return {
    plus: lineData(plus),
    minus: lineData(minus),
    adx: lineData(adx),
    signals,
  };
}

function chartColorWithAlpha(color, alpha) {
  const value = String(color || "").trim();
  const match = /^#([0-9a-f]{6})$/i.exec(value);
  if (!match) return value;
  const numeric = Number.parseInt(match[1], 16);
  return `rgba(${(numeric >> 16) & 255},${(numeric >> 8) & 255},${numeric & 255},${alpha})`;
}

function chartLabelTextColor(color) {
  const match = /^#([0-9a-f]{6})$/i.exec(String(color || "").trim());
  if (!match) return "#061018";
  const numeric = Number.parseInt(match[1], 16);
  const red = (numeric >> 16) & 255;
  const green = (numeric >> 8) & 255;
  const blue = numeric & 255;
  return (red * 299 + green * 587 + blue * 114) / 1000 >= 145 ? "#061018" : "#f8fafc";
}

