  const applyDailyTradeTemplate = (value) => {
    setDailyTradeAmount(value);
    const numeric = Number(value || 0);
    if (!Number.isFinite(numeric) || numeric <= 0) return;
    const perTrade = Math.max(Math.round(numeric * 0.1), 1);
    setTradeAmount(String(perTrade));
    const currentStopPercent = Math.max(Number(stopLossPercent || 0), 0.01);
    setStopLossAmount((perTrade * currentStopPercent / 100).toFixed(2));
  };

  const syncStopLossPercentFromAmount = (value, activeTradeAmount = tradeAmount) => {
    setStopLossAmount(value);
    const stopAmount = Number(value || 0);
    const capital = Number(activeTradeAmount || 0);
    if (!Number.isFinite(stopAmount) || !Number.isFinite(capital) || capital <= 0 || stopAmount <= 0) return;
    setStopLossPercent(((stopAmount / capital) * 100).toFixed(2));
  };

  const syncStopLossAmountFromPercent = (value, activeTradeAmount = tradeAmount) => {
    setStopLossPercent(value);
    const stopPercent = Number(value || 0);
    const capital = Number(activeTradeAmount || 0);
    if (!Number.isFinite(stopPercent) || !Number.isFinite(capital) || capital <= 0 || stopPercent <= 0) return;
    setStopLossAmount((capital * stopPercent / 100).toFixed(2));
  };

  const updateTradeAmount = (value) => {
    setTradeAmount(value);
    const capital = Number(value || 0);
    const stopPercent = Number(stopLossPercent || 0);
    if (!Number.isFinite(capital) || capital <= 0 || !Number.isFinite(stopPercent) || stopPercent <= 0) return;
    setStopLossAmount((capital * stopPercent / 100).toFixed(2));
  };

