  const mag7OptionRows = mag7OptionWatchlistSource.map((source) => {
    const mapped = optionSymbolMappings[source] || source;
    const aliases = optionAliasMap[mapped] || [];
    return { source, mapped, aliases };
  });
  const mag7ScannerSearchTerm = mag7ScannerSearch.trim().toUpperCase();
  const visibleMag7OptionRows = mag7OptionRows.filter((row) => {
    if (!mag7ScannerSearchTerm) return true;
    return String(row.source || "").toUpperCase().includes(mag7ScannerSearchTerm)
      || String(row.mapped || "").toUpperCase().includes(mag7ScannerSearchTerm);
  });

  const optionIdeaRows = (dashboard.optionCandidateResults || [])
