      symbol: row.symbol,
      bias: optionStructureLabel,
      trigger: row.option_rule_trigger_match || row.setup_name || "No trigger",
      expiry: "Next Weekly",
      strike: optionDeltaTarget ? `Delta <= ${optionDeltaTarget}` : "ATM / 1 ITM",
      deltaBand: optionDeltaTarget ? `<= ${optionDeltaTarget}` : "Planner default",
      commonLogic: optionCommonGateSummary(row),
      chainQuality: optionSpreadFilter ? `Spread ${optionSpreadFilter}` : "Review spread",
      oneHourPriceChangePct: row.option_one_hour_price_change_pct ?? row.option_one_hour_close_change_pct,
      fourHourPriceChangePct: row.option_four_hour_price_change_pct ?? row.option_four_hour_close_change_pct,
      optionRulePassed: row.option_rule_passed,
      status: row.option_rule_passed ? "Ready" : (row.option_rule_rejection_reason || "Blocked"),
